_MATCH_THRESHOLD = 18.0  # mean absolute difference over the 256-value fingerprint


def _fingerprint(image: np.ndarray) -> np.ndarray:
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    small = cv2.resize(gray, (16, 16), interpolation=cv2.INTER_AREA)
    return small.astype(np.int16).flatten()


def match_reference(image: np.ndarray) -> list[dict] | None:
    """Return curated annotations if this image matches a known reference
    photo, else None (caller should fall back to random behavior)."""
    fp = _fingerprint(image)
    best_name, best_score = None, float("inf")
    for name, ref in _FINGERPRINTS.items():
        score = float(np.mean(np.abs(fp - np.array(ref, dtype=np.int16))))
        if score < best_score:
            best_name, best_score = name, score

    if best_score < _MATCH_THRESHOLD:
        return _ANNOTATIONS[best_name]
    return None
